pub fn step(self: *RSF, x1: []const f32, x2: []const f32,
            t1: []const f32, t2: []const f32,
            lr: f32, momentum: f32) RSFError!f32 {
    // Ha van gpu_ctx és futhark backend, egyetlen kernel hívás:
    if (self.gpu_ctx) |gctx| {
        if (gctx.fut_ctx) |fc| {
            // futhark_entry_trainingstep(...) - ez a compute.fut-ban van
            // visszaadja: ws, bs, wt, bt, vws, vbs, vwt, vbt, loss
            // majd vissza kell írni a core.layers-be
